/**
 * KRC Labs — Unified Window Manager
 * Browser-in-Browser Tabbed Desktop GUI Window Orchestrator.
 * Features:
 *  - Unified browser window tab strip UI (Chrome/Arc style)
 *  - Real-time tab switching between Guide & Theme Studio
 *  - Seamless Tear-off / Split mode & Merge to Tabs
 *  - Unified position & opacity synchronization
 *  - LocalStorage persistence across F5 reloads
 *  - 10-Language Parity & Zero AI mentions
 */

import { LanguageCode } from '../types';
import { TRANSLATIONS } from '../locales';
import { HelpModal } from './HelpModal';
import { CustomThemeModal } from './CustomThemeModal';

export type WindowMode = 'unified' | 'split';
export type WindowTab = 'guide' | 'theme';

export class UnifiedWindowManager {
  private static readonly STORAGE_MODE_KEY = 'krc_unified_window_mode';
  private static readonly STORAGE_TAB_KEY = 'krc_unified_window_tab';

  private helpModal: HelpModal;
  private customModal: CustomThemeModal;
  private currentMode: WindowMode = 'unified';
  private activeTab: WindowTab = 'guide';
  private currentLang: LanguageCode = 'ko';

  constructor(helpModal: HelpModal, customModal: CustomThemeModal) {
    this.helpModal = helpModal;
    this.customModal = customModal;
  }

  public init(lang: LanguageCode = 'ko'): void {
    this.currentLang = lang;

    // 1. Restore mode from local storage (default to 'unified')
    const savedMode = localStorage.getItem(UnifiedWindowManager.STORAGE_MODE_KEY);
    if (savedMode === 'split' || savedMode === 'unified') {
      this.currentMode = savedMode;
    } else {
      this.currentMode = 'unified';
    }

    // 2. Restore active tab from local storage (default to 'guide')
    const savedTab = localStorage.getItem(UnifiedWindowManager.STORAGE_TAB_KEY);
    if (savedTab === 'theme' || savedTab === 'guide') {
      this.activeTab = savedTab;
    } else {
      this.activeTab = 'guide';
    }

    this.bindTabEvents();
    this.bindSplitButtons();
    this.updateTabStyles();
    this.updateTexts();
  }

  public setLanguage(lang: LanguageCode): void {
    this.currentLang = lang;
    this.updateTexts();
  }

  public getMode(): WindowMode {
    return this.currentMode;
  }

  public getActiveTab(): WindowTab {
    return this.activeTab;
  }

  /**
   * Opens the window respecting current unified / split mode.
   */
  public open(targetTab: WindowTab = 'guide'): void {
    this.activeTab = targetTab;
    localStorage.setItem(UnifiedWindowManager.STORAGE_TAB_KEY, targetTab);

    if (this.currentMode === 'unified') {
      this.openUnified(targetTab);
    } else {
      // Split mode: open the requested window
      if (targetTab === 'guide') {
        this.helpModal.open();
      } else {
        this.customModal.open();
      }
    }
    this.updateTabStyles();
  }

  /**
   * Toggles the window state.
   */
  public toggle(targetTab: WindowTab = 'guide'): void {
    if (this.currentMode === 'unified') {
      const isGuideOpen = this.helpModal.isOpen();
      const isCustomOpen = this.customModal.isOpen();

      if (isGuideOpen || isCustomOpen) {
        // If clicking same active tab, toggle close. If different tab, switch to it!
        if (this.activeTab === targetTab) {
          this.closeAll();
        } else {
          this.openUnified(targetTab);
        }
      } else {
        this.openUnified(targetTab);
      }
    } else {
      // Split mode: toggle specific modal
      if (targetTab === 'guide') {
        this.helpModal.toggle();
      } else {
        this.customModal.toggle();
      }
    }
    this.updateTabStyles();
  }

  /**
   * Open in unified browser tab mode.
   * Keeps coordinates synchronized between windows so tabs transition without jumping.
   */
  private openUnified(tab: WindowTab): void {
    this.activeTab = tab;
    localStorage.setItem(UnifiedWindowManager.STORAGE_TAB_KEY, tab);

    if (tab === 'guide') {
      if (this.customModal.isOpen() && this.customModal.windowEl) {
        this.syncGeometry(this.customModal.windowEl, this.helpModal.windowEl);
        this.customModal.close();
      }
      this.helpModal.open();
    } else {
      if (this.helpModal.isOpen() && this.helpModal.windowEl) {
        this.syncGeometry(this.helpModal.windowEl, this.customModal.windowEl);
        this.helpModal.close();
      }
      this.customModal.open();
    }

    this.updateTabStyles();
  }

  /**
   * Synchronize position, dimensions, and opacity between source and target windows
   */
  private syncGeometry(source: HTMLElement | null, target: HTMLElement | null): void {
    if (!source || !target) return;
    const style = window.getComputedStyle(source);
    target.style.left = source.style.left || style.left;
    target.style.top = source.style.top || style.top;
    if (source.style.width) target.style.width = source.style.width;
    if (source.style.height) target.style.height = source.style.height;

    const op = source.style.getPropertyValue('--window-opacity');
    if (op) {
      target.style.setProperty('--window-opacity', op);
      target.style.opacity = op;
    }
  }

  public closeAll(): void {
    this.helpModal.close();
    this.customModal.close();
  }

  /**
   * Toggle between unified tab mode and split window mode.
   */
  public toggleMode(): void {
    if (this.currentMode === 'unified') {
      this.setMode('split');
    } else {
      this.setMode('unified');
    }
  }

  public setMode(mode: WindowMode): void {
    this.currentMode = mode;
    localStorage.setItem(UnifiedWindowManager.STORAGE_MODE_KEY, mode);

    const t = TRANSLATIONS[this.currentLang] || TRANSLATIONS.ko;

    if (mode === 'split') {
      // Split windows apart
      this.helpModal.open();
      this.customModal.open();

      // Slightly offset custom modal if overlapping exactly
      if (this.helpModal.windowEl && this.customModal.windowEl) {
        const hRect = this.helpModal.windowEl.getBoundingClientRect();
        const vpW = window.innerWidth;
        if (vpW > 768) {
          this.customModal.windowEl.style.left = `${Math.min(vpW - 460, hRect.left + 40)}px`;
          this.customModal.windowEl.style.top = `${hRect.top + 50}px`;
        }
      }

      this.showToast(t.windowModeSplit + ': ' + (this.currentLang === 'ko' ? '독립 창으로 분리되었습니다' : 'Separated into standalone windows'));
    } else {
      // Merge into unified tab window
      if (this.activeTab === 'guide') {
        this.customModal.close();
        this.helpModal.open();
      } else {
        this.helpModal.close();
        this.customModal.open();
      }
      this.showToast(t.windowModeUnified + ': ' + (this.currentLang === 'ko' ? '단일 탭 창으로 통합되었습니다' : 'Merged into unified tabbed window'));
    }

    this.updateTabStyles();
    this.updateTexts();
  }

  private bindTabEvents(): void {
    // Both Help & Custom windows have tab strips
    const tabButtons = document.querySelectorAll<HTMLButtonElement>('.browser-tab');
    tabButtons.forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const tab = btn.getAttribute('data-tab') as WindowTab | null;
        if (tab) {
          this.openUnified(tab);
        }
      });
    });

    // Close buttons on individual tabs
    const closeTabBtns = document.querySelectorAll<HTMLElement>('.browser-tab-close');
    closeTabBtns.forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        this.closeAll();
      });
    });
  }

  private bindSplitButtons(): void {
    const splitBtns = [
      document.getElementById('customWindowSplitBtn'),
      document.getElementById('helpWindowSplitBtn'),
    ];

    splitBtns.forEach((btn) => {
      btn?.addEventListener('click', (e) => {
        e.stopPropagation();
        this.toggleMode();
      });
    });
  }

  private updateTabStyles(): void {
    const isUnified = this.currentMode === 'unified';

    // 1. Update active tab highlights
    const allTabs = document.querySelectorAll<HTMLElement>('.browser-tab');
    allTabs.forEach((tabEl) => {
      const tabType = tabEl.getAttribute('data-tab');
      if (tabType === this.activeTab) {
        tabEl.classList.add('active');
        tabEl.setAttribute('aria-selected', 'true');
      } else {
        tabEl.classList.remove('active');
        tabEl.setAttribute('aria-selected', 'false');
      }

      // In split mode, each window can emphasize its own tab
      if (!isUnified) {
        const isInsideHelp = tabEl.closest('#helpModal') !== null;
        const isInsideCustom = tabEl.closest('#customThemeModal') !== null;
        if (isInsideHelp && tabType === 'guide') {
          tabEl.classList.add('active');
        } else if (isInsideCustom && tabType === 'theme') {
          tabEl.classList.add('active');
        } else {
          tabEl.classList.remove('active');
        }
      }
    });

    // 2. Update split/merge button icons and tooltips
    const t = TRANSLATIONS[this.currentLang] || TRANSLATIONS.ko;
    const splitBtnTitle = isUnified ? t.windowModeSplit : t.windowModeUnified;

    const splitSvg = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="12" y1="3" x2="12" y2="21"/></svg>`;
    const mergeSvg = `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M4 6h16M4 12h16M4 18h16"/><rect x="2" y="3" width="20" height="18" rx="2"/></svg>`;

    const customSplitBtn = document.getElementById('customWindowSplitBtn');
    if (customSplitBtn) {
      customSplitBtn.title = splitBtnTitle;
      customSplitBtn.setAttribute('aria-label', splitBtnTitle);
      customSplitBtn.innerHTML = isUnified ? splitSvg : mergeSvg;
    }

    const helpSplitBtn = document.getElementById('helpWindowSplitBtn');
    if (helpSplitBtn) {
      helpSplitBtn.title = splitBtnTitle;
      helpSplitBtn.setAttribute('aria-label', splitBtnTitle);
      helpSplitBtn.innerHTML = isUnified ? splitSvg : mergeSvg;
    }
  }

  public updateTexts(): void {
    const t = TRANSLATIONS[this.currentLang] || TRANSLATIONS.ko;

    const guideTitles = [
      document.getElementById('customTabGuideTitle'),
      document.getElementById('helpTabGuideTitle'),
    ];
    guideTitles.forEach((el) => {
      if (el) el.textContent = t.windowTabGuide;
    });

    const themeTitles = [
      document.getElementById('customTabThemeTitle'),
      document.getElementById('helpTabThemeTitle'),
    ];
    themeTitles.forEach((el) => {
      if (el) el.textContent = t.windowTabStudio;
    });

    this.updateTabStyles();
  }

  private showToast(message: string): void {
    const toast = document.getElementById('krcToast');
    if (!toast) return;
    toast.textContent = message;
    toast.classList.add('visible');
    setTimeout(() => {
      toast.classList.remove('visible');
    }, 2800);
  }
}
