/**
 * KRC Labs — TableOfContents Component
 * Interactive Quick-Jump Navigator & ScrollSpy for Showcase sections:
 *  - #hero (Overview & Lab Headline)
 *  - #cluster (Node Cluster Telemetry)
 *  - #systems (10 Core Runtimes Catalog)
 *  - #console (Interactive Terminal Shell)
 *  - #faq (Operational Guide & FAQ)
 */

import { LanguageCode } from '../types';
import { TRANSLATIONS } from '../locales';

export interface TocSectionItem {
  id: string;
  icon: string;
  i18nKey: 'tocOverview' | 'tocTelemetry' | 'tocSystems' | 'tocConsole' | 'tocFaq';
}

export const TOC_SECTIONS: TocSectionItem[] = [
  { id: 'hero', icon: '🏛️', i18nKey: 'tocOverview' },
  { id: 'cluster', icon: '⚡', i18nKey: 'tocTelemetry' },
  { id: 'systems', icon: '📦', i18nKey: 'tocSystems' },
  { id: 'console', icon: '💻', i18nKey: 'tocConsole' },
  { id: 'faq', icon: '❓', i18nKey: 'tocFaq' },
];

export class TableOfContents {
  private currentLang: LanguageCode = 'ko';
  private containerEl: HTMLElement | null = null;
  private observer: IntersectionObserver | null = null;
  private activeSectionId: string = 'hero';

  public init(lang: LanguageCode = 'ko'): void {
    this.currentLang = lang;
    this.containerEl = document.getElementById('tableOfContents');

    this.bindClicks();
    this.initScrollSpy();
    this.updateTexts();
  }

  public setLanguage(lang: LanguageCode): void {
    this.currentLang = lang;
    this.updateTexts();
  }

  public getActiveSection(): string {
    return this.activeSectionId;
  }

  public setActiveSection(sectionId: string): void {
    this.activeSectionId = sectionId;
    if (!this.containerEl) return;

    const items = this.containerEl.querySelectorAll<HTMLAnchorElement>('.toc-nav-chip');
    items.forEach((chip) => {
      const targetId = chip.getAttribute('data-target-id');
      if (targetId === sectionId) {
        chip.classList.add('active');
        chip.setAttribute('aria-current', 'true');
      } else {
        chip.classList.remove('active');
        chip.removeAttribute('aria-current');
      }
    });
  }

  private updateTexts(): void {
    const t = TRANSLATIONS[this.currentLang] || TRANSLATIONS.ko;

    const titleEl = document.getElementById('tocTitleLabel');
    if (titleEl) titleEl.textContent = t.tocTitle;

    for (const sec of TOC_SECTIONS) {
      const chipText = document.querySelector<HTMLElement>(`[data-toc-i18n="${sec.i18nKey}"]`);
      if (chipText) {
        chipText.textContent = t[sec.i18nKey];
      }
    }
  }

  private bindClicks(): void {
    if (!this.containerEl) return;

    this.containerEl.addEventListener('click', (e) => {
      const chip = (e.target as HTMLElement).closest('.toc-nav-chip') as HTMLAnchorElement | null;
      if (!chip) return;

      const targetId = chip.getAttribute('data-target-id');
      if (!targetId) return;

      e.preventDefault();
      const targetEl = document.getElementById(targetId);
      if (targetEl) {
        targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
        this.setActiveSection(targetId);
        // Push state without page jump
        history.pushState(null, '', `#${targetId}`);
      }
    });
  }

  private initScrollSpy(): void {
    if (typeof IntersectionObserver === 'undefined') {
      this.bindWindowScrollFallback();
      return;
    }

    const sectionElements: HTMLElement[] = [];
    for (const sec of TOC_SECTIONS) {
      const el = document.getElementById(sec.id);
      if (el) sectionElements.push(el);
    }

    if (sectionElements.length === 0) {
      this.bindWindowScrollFallback();
      return;
    }

    // ScrollSpy observer with a comfortable top offset
    this.observer = new IntersectionObserver(
      (entries) => {
        const visibleEntries = entries.filter((ent) => ent.isIntersecting);
        if (visibleEntries.length > 0) {
          // Sort by intersectionRatio descending
          visibleEntries.sort((a, b) => b.intersectionRatio - a.intersectionRatio);
          const topVisible = visibleEntries[0].target.id;
          if (topVisible) {
            this.setActiveSection(topVisible);
          }
        }
      },
      {
        root: null,
        rootMargin: '-80px 0px -40% 0px',
        threshold: [0.1, 0.3, 0.6],
      }
    );

    sectionElements.forEach((el) => this.observer?.observe(el));
  }

  private bindWindowScrollFallback(): void {
    const handleScroll = () => {
      const scrollPos = window.scrollY + 140;
      let current = TOC_SECTIONS[0].id;

      for (const sec of TOC_SECTIONS) {
        const el = document.getElementById(sec.id);
        if (el) {
          const top = el.offsetTop;
          if (scrollPos >= top) {
            current = sec.id;
          }
        }
      }
      this.setActiveSection(current);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();
  }
}
