/**
 * KRC Labs — CustomThemeModal (Floating Window GUI)
 * Movable, Resizable, and Collapsible Desktop-class Window Studio.
 * Inherits and leverages the common FloatingWindow engine for DRY design.
 * Allows developers to craft, preview in real time, and persist custom palettes.
 */

import { CustomPalette, CustomDesignEngineConfig, LanguageCode } from '../types';
import { TRANSLATIONS } from '../locales';
import { FloatingWindow } from './FloatingWindow';

export const DEFAULT_DESIGN_CONFIG: CustomDesignEngineConfig = {
  fontFamily: 'system',
  fontScale: 100,
  borderRadius: 6,
  glassBlur: 18,
  density: 'normal',
};

export const DEFAULT_CUSTOM_PALETTE: CustomPalette = {
  bg: '#14171f',
  surface: '#1d222d',
  surfaceAlt: '#272e3d',
  border: '#384256',
  accent: '#8b5cf6',
  textPrimary: '#f1f5f9',
};

export const CUSTOM_PRESETS: Array<{ id: string; name: string; palette: CustomPalette }> = [
  {
    id: 'violet',
    name: 'Midnight Violet',
    palette: {
      bg: '#0c0a17',
      surface: '#181329',
      surfaceAlt: '#241c3d',
      border: '#3c2e63',
      accent: '#a855f7',
      textPrimary: '#f1f5f9',
    },
  },
  {
    id: 'nord',
    name: 'Nordic Frost',
    palette: {
      bg: '#1e222a',
      surface: '#282c34',
      surfaceAlt: '#323842',
      border: '#434b57',
      accent: '#61afef',
      textPrimary: '#abb2bf',
    },
  },
  {
    id: 'solar',
    name: 'Solarized Amber',
    palette: {
      bg: '#002b36',
      surface: '#073642',
      surfaceAlt: '#0e4453',
      border: '#195566',
      accent: '#b58900',
      textPrimary: '#93a1a1',
    },
  },
  {
    id: 'oled',
    name: 'OLED Pure Black',
    palette: {
      bg: '#000000',
      surface: '#121212',
      surfaceAlt: '#1f1f1f',
      border: '#2c2c2c',
      accent: '#38bdf8',
      textPrimary: '#ffffff',
    },
  },
];

export class CustomThemeModal extends FloatingWindow {
  private static readonly PALETTE_STORAGE_KEY = 'krc_custom_theme';
  private static readonly DESIGN_STORAGE_KEY = 'krc_custom_design_engine';
  private static readonly STORAGE_OPACITY_KEY = 'krc_custom_win_opacity';
  public static readonly DEFAULT_OPACITY = 85;
  public static readonly MIN_OPACITY = 40;
  public static readonly MAX_OPACITY = 100;

  private currentPalette: CustomPalette = { ...DEFAULT_CUSTOM_PALETTE };
  private currentDesign: CustomDesignEngineConfig = { ...DEFAULT_DESIGN_CONFIG };
  private onApplyCallback: ((palette: CustomPalette) => void) | null = null;

  private opacityRange: HTMLInputElement | null = null;
  private opacityValBadge: HTMLElement | null = null;
  private opacityLabelEl: HTMLElement | null = null;
  private currentOpacity: number = CustomThemeModal.DEFAULT_OPACITY;

  constructor() {
    super({
      containerId: 'customThemeModal',
      windowId: 'customWindowRoot',
      titlebarId: 'customWindowTitlebar',
      collapseBtnId: 'customWindowCollapseBtn',
      closeBtnId: 'customModalClose',
      resizeHandleId: 'customWindowResizeHandle',
      modeBadgeId: 'customWindowModeBadge',
      storageKey: 'krc_custom_win_pos',
      initialPos: {
        leftOffsetFromRight: 24,
        top: 76,
        width: 520,
        height: 560,
      },
      minWidth: 320,
      minHeight: 220,
      badgeActiveText: 'Live GUI',
      badgeCollapsedText: '접힘',
    });
  }

  public override init(lang: LanguageCode = 'ko'): void {
    super.init(lang);
    this.loadStoredPalette();
    this.loadStoredDesign();
    this.initOpacityControl();
    this.bindStudioEvents();
    this.updateTexts();
  }

  public override setLanguage(lang: LanguageCode): void {
    super.setLanguage(lang);
    this.updateTexts();
  }

  public onApply(callback: (palette: CustomPalette) => void): void {
    this.onApplyCallback = callback;
  }

  public override open(): void {
    this.loadStoredPalette();
    this.syncInputsWithState();
    this.applyOpacity(this.currentOpacity);
    super.open();
  }

  private initOpacityControl(): void {
    const controlEl = document.getElementById('customOpacityControl');
    if (controlEl) {
      const stopEvents = ['mousedown', 'touchstart', 'click', 'dblclick'];
      stopEvents.forEach((evtName) => {
        controlEl.addEventListener(evtName, (e) => {
          e.stopPropagation();
        });
      });
    }

    this.opacityRange = document.getElementById('customWindowOpacityRange') as HTMLInputElement | null;
    this.opacityValBadge = document.getElementById('customWindowOpacityVal');
    this.opacityLabelEl = document.getElementById('customOpacityLabel');

    const saved = localStorage.getItem(CustomThemeModal.STORAGE_OPACITY_KEY);
    if (saved) {
      const parsed = parseInt(saved, 10);
      if (!isNaN(parsed) && parsed >= CustomThemeModal.MIN_OPACITY && parsed <= CustomThemeModal.MAX_OPACITY) {
        this.currentOpacity = parsed;
      }
    }

    this.applyOpacity(this.currentOpacity);

    if (this.opacityRange) {
      this.opacityRange.value = String(this.currentOpacity);
      this.opacityRange.addEventListener('input', (e) => {
        e.stopPropagation();
        const val = parseInt(this.opacityRange?.value || String(CustomThemeModal.DEFAULT_OPACITY), 10);
        this.applyOpacity(val);
        localStorage.setItem(CustomThemeModal.STORAGE_OPACITY_KEY, String(val));
      });
    }
  }

  public applyOpacity(val: number): void {
    const clamped = Math.max(CustomThemeModal.MIN_OPACITY, Math.min(CustomThemeModal.MAX_OPACITY, val));
    this.currentOpacity = clamped;

    if (this.windowEl) {
      this.windowEl.style.setProperty('--window-opacity', `${clamped / 100}`);
      this.windowEl.style.opacity = `${clamped / 100}`;
    }

    if (this.opacityValBadge) {
      this.opacityValBadge.textContent = `${clamped}%`;
    }

    if (this.opacityRange && this.opacityRange.value !== String(clamped)) {
      this.opacityRange.value = String(clamped);
    }
  }

  public getOpacity(): number {
    return this.currentOpacity;
  }

  public getPalette(): CustomPalette {
    return { ...this.currentPalette };
  }

  public applyPaletteToDocument(palette: CustomPalette): void {
    const root = document.documentElement;
    root.style.setProperty('--bg', palette.bg);
    root.style.setProperty('--surface', palette.surface);
    root.style.setProperty('--surface-alt', palette.surfaceAlt);
    root.style.setProperty('--border', palette.border);
    root.style.setProperty('--accent', palette.accent);
    root.style.setProperty('--accent-hover', palette.accent);
    root.style.setProperty('--accent-bg', `${palette.accent}22`);
    root.style.setProperty('--accent-border', `${palette.accent}44`);
    root.style.setProperty('--text-primary', palette.textPrimary);
  }

  public removeCustomOverrides(): void {
    const root = document.documentElement;
    root.style.removeProperty('--bg');
    root.style.removeProperty('--surface');
    root.style.removeProperty('--surface-alt');
    root.style.removeProperty('--border');
    root.style.removeProperty('--accent');
    root.style.removeProperty('--accent-hover');
    root.style.removeProperty('--accent-bg');
    root.style.removeProperty('--accent-border');
    root.style.removeProperty('--text-primary');
  }

  private loadStoredPalette(): void {
    try {
      const raw = localStorage.getItem(CustomThemeModal.PALETTE_STORAGE_KEY);
      if (raw) {
        this.currentPalette = { ...DEFAULT_CUSTOM_PALETTE, ...JSON.parse(raw) };
      }
    } catch {
      this.currentPalette = { ...DEFAULT_CUSTOM_PALETTE };
    }
  }

  private savePalette(palette: CustomPalette): void {
    this.currentPalette = { ...palette };
    localStorage.setItem(CustomThemeModal.PALETTE_STORAGE_KEY, JSON.stringify(palette));
  }

  private loadStoredDesign(): void {
    try {
      const raw = localStorage.getItem(CustomThemeModal.DESIGN_STORAGE_KEY);
      if (raw) {
        this.currentDesign = { ...DEFAULT_DESIGN_CONFIG, ...JSON.parse(raw) };
      }
    } catch {
      this.currentDesign = { ...DEFAULT_DESIGN_CONFIG };
    }
    this.applyDesignConfig(this.currentDesign, false);
  }

  public saveDesignConfig(config: CustomDesignEngineConfig): void {
    this.currentDesign = { ...config };
    localStorage.setItem(CustomThemeModal.DESIGN_STORAGE_KEY, JSON.stringify(this.currentDesign));
  }

  public applyDesignConfig(config: CustomDesignEngineConfig, persist: boolean = true): void {
    this.currentDesign = { ...config };
    const root = document.documentElement;

    // 1. Font Family
    let fontVal = '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif';
    if (config.fontFamily === 'mono') {
      fontVal = "'JetBrains Mono', 'Fira Code', ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace";
    } else if (config.fontFamily === 'neo') {
      fontVal = "'Pretendard', -apple-system, BlinkMacSystemFont, 'SF Pro Text', Roboto, sans-serif";
    } else if (config.fontFamily === 'serif') {
      fontVal = "Charter, Georgia, Cambria, 'Times New Roman', serif";
    }
    root.style.setProperty('--font-family-base', fontVal);

    // 2. Font Scale
    root.style.setProperty('--font-scale', `${config.fontScale / 100}`);

    // 3. Radius
    root.style.setProperty('--radius-ui', `${config.borderRadius}px`);

    // 4. Blur
    root.style.setProperty('--window-blur', `${config.glassBlur}px`);

    // 5. Density
    const densityMult = config.density === 'compact' ? 0.88 : config.density === 'relaxed' ? 1.15 : 1.0;
    root.style.setProperty('--density-scale', `${densityMult}`);

    this.syncDesignInputs();
    if (persist) {
      this.saveDesignConfig(this.currentDesign);
    }
  }

  private syncDesignInputs(): void {
    const fontSelect = document.getElementById('customFontSelect') as HTMLSelectElement | null;
    const fontScaleRange = document.getElementById('customFontScaleRange') as HTMLInputElement | null;
    const fontScaleVal = document.getElementById('customFontScaleVal');
    const radiusRange = document.getElementById('customRadiusRange') as HTMLInputElement | null;
    const radiusVal = document.getElementById('customRadiusVal');
    const blurRange = document.getElementById('customBlurRange') as HTMLInputElement | null;
    const blurVal = document.getElementById('customBlurVal');

    if (fontSelect) fontSelect.value = this.currentDesign.fontFamily;
    if (fontScaleRange) fontScaleRange.value = String(this.currentDesign.fontScale);
    if (fontScaleVal) fontScaleVal.textContent = `${this.currentDesign.fontScale}%`;
    if (radiusRange) radiusRange.value = String(this.currentDesign.borderRadius);
    if (radiusVal) radiusVal.textContent = `${this.currentDesign.borderRadius}px`;
    if (blurRange) blurRange.value = String(this.currentDesign.glassBlur);
    if (blurVal) blurVal.textContent = `${this.currentDesign.glassBlur}px`;

    const densityBtns = document.querySelectorAll<HTMLButtonElement>('#customDensityGroup .density-btn');
    densityBtns.forEach((btn) => {
      const d = btn.getAttribute('data-density');
      if (d === this.currentDesign.density) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    });
  }

  private bindStudioEvents(): void {
    // 1. Presets buttons
    const presetBtns = document.querySelectorAll<HTMLButtonElement>('.custom-preset-btn');
    presetBtns.forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const pid = btn.getAttribute('data-preset-id');
        const match = CUSTOM_PRESETS.find((p) => p.id === pid);
        if (match) {
          this.applyPreset(match.palette);
        }
      });
    });

    // 2. Color picker inputs & wrapper click trigger
    const colorWrappers = document.querySelectorAll('.color-input-wrapper');
    colorWrappers.forEach((wrapper) => {
      wrapper.addEventListener('click', (e) => {
        if ((e.target as HTMLElement).tagName !== 'INPUT') {
          const inp = wrapper.querySelector<HTMLInputElement>('input[type="color"]');
          inp?.click();
        }
      });
    });

    const bgInput = document.getElementById('customBgInput') as HTMLInputElement | null;
    const surfaceInput = document.getElementById('customSurfaceInput') as HTMLInputElement | null;
    const accentInput = document.getElementById('customAccentInput') as HTMLInputElement | null;
    const textInput = document.getElementById('customTextInput') as HTMLInputElement | null;

    bgInput?.addEventListener('input', (e) => {
      this.updateColorField('bg', (e.target as HTMLInputElement).value);
    });

    surfaceInput?.addEventListener('input', (e) => {
      this.updateColorField('surface', (e.target as HTMLInputElement).value);
    });

    accentInput?.addEventListener('input', (e) => {
      this.updateColorField('accent', (e.target as HTMLInputElement).value);
    });

    textInput?.addEventListener('input', (e) => {
      this.updateColorField('textPrimary', (e.target as HTMLInputElement).value);
    });

    // 3. Reset Button (Palette & Design Engine Reset)
    const resetBtn = document.getElementById('customModalReset');
    resetBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.applyPreset(DEFAULT_CUSTOM_PALETTE);
      this.applyDesignConfig(DEFAULT_DESIGN_CONFIG, true);
    });

    // 4. Save & Apply Button
    const saveBtn = document.getElementById('customModalSave');
    saveBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.savePalette(this.currentPalette);
      this.applyPaletteToDocument(this.currentPalette);
      this.saveDesignConfig(this.currentDesign);
      this.onApplyCallback?.(this.currentPalette);
      this.close();
    });

    // 5. Design Engine Controls
    const fontSelect = document.getElementById('customFontSelect') as HTMLSelectElement | null;
    fontSelect?.addEventListener('change', (e) => {
      const val = (e.target as HTMLSelectElement).value as any;
      this.applyDesignConfig({ ...this.currentDesign, fontFamily: val });
    });

    const fontScaleRange = document.getElementById('customFontScaleRange') as HTMLInputElement | null;
    fontScaleRange?.addEventListener('input', (e) => {
      const val = parseInt((e.target as HTMLInputElement).value, 10);
      this.applyDesignConfig({ ...this.currentDesign, fontScale: val });
    });

    const radiusRange = document.getElementById('customRadiusRange') as HTMLInputElement | null;
    radiusRange?.addEventListener('input', (e) => {
      const val = parseInt((e.target as HTMLInputElement).value, 10);
      this.applyDesignConfig({ ...this.currentDesign, borderRadius: val });
    });

    const blurRange = document.getElementById('customBlurRange') as HTMLInputElement | null;
    blurRange?.addEventListener('input', (e) => {
      const val = parseInt((e.target as HTMLInputElement).value, 10);
      this.applyDesignConfig({ ...this.currentDesign, glassBlur: val });
    });

    const densityBtns = document.querySelectorAll<HTMLButtonElement>('#customDensityGroup .density-btn');
    densityBtns.forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const d = (btn.getAttribute('data-density') || 'normal') as any;
        this.applyDesignConfig({ ...this.currentDesign, density: d });
      });
    });
  }

  private applyPreset(palette: CustomPalette): void {
    this.currentPalette = { ...palette };
    this.syncInputsWithState();
    this.applyPaletteToDocument(this.currentPalette);
    this.savePalette(this.currentPalette);
    this.onApplyCallback?.(this.currentPalette);
  }

  private updateColorField(key: keyof CustomPalette, value: string): void {
    this.currentPalette[key] = value;
    if (key === 'surface') {
      this.currentPalette.surfaceAlt = this.adjustBrightness(value, 10);
      this.currentPalette.border = this.adjustBrightness(value, 20);
    }
    this.applyPaletteToDocument(this.currentPalette);
    this.syncHexLabels();
  }

  private syncInputsWithState(): void {
    const bgInput = document.getElementById('customBgInput') as HTMLInputElement | null;
    const surfaceInput = document.getElementById('customSurfaceInput') as HTMLInputElement | null;
    const accentInput = document.getElementById('customAccentInput') as HTMLInputElement | null;
    const textInput = document.getElementById('customTextInput') as HTMLInputElement | null;

    if (bgInput) bgInput.value = this.currentPalette.bg;
    if (surfaceInput) surfaceInput.value = this.currentPalette.surface;
    if (accentInput) accentInput.value = this.currentPalette.accent;
    if (textInput) textInput.value = this.currentPalette.textPrimary;

    this.syncHexLabels();
  }

  private syncHexLabels(): void {
    const bgHex = document.getElementById('customBgHex');
    const surfaceHex = document.getElementById('customSurfaceHex');
    const accentHex = document.getElementById('customAccentHex');
    const textHex = document.getElementById('customTextHex');

    if (bgHex) bgHex.textContent = this.currentPalette.bg;
    if (surfaceHex) surfaceHex.textContent = this.currentPalette.surface;
    if (accentHex) accentHex.textContent = this.currentPalette.accent;
    if (textHex) textHex.textContent = this.currentPalette.textPrimary;

    // Live preview card update
    const previewBox = document.getElementById('customLivePreview');
    if (previewBox) {
      previewBox.style.backgroundColor = this.currentPalette.bg;
      previewBox.style.borderColor = this.currentPalette.border;
      const previewText = previewBox.querySelector<HTMLElement>('.preview-card-text');
      const previewAccent = previewBox.querySelector<HTMLElement>('.preview-card-accent');
      if (previewText) previewText.style.color = this.currentPalette.textPrimary;
      if (previewAccent) {
        previewAccent.style.backgroundColor = this.currentPalette.accent;
        previewAccent.style.color = '#ffffff';
      }
    }
  }

  private adjustBrightness(hex: string, percent: number): string {
    const clean = hex.replace('#', '');
    const num = parseInt(clean, 16);
    let r = (num >> 16) + Math.round((255 * percent) / 100);
    let g = ((num >> 8) & 0x00ff) + Math.round((255 * percent) / 100);
    let b = (num & 0x0000ff) + Math.round((255 * percent) / 100);

    r = Math.min(255, Math.max(0, r));
    g = Math.min(255, Math.max(0, g));
    b = Math.min(255, Math.max(0, b));

    return `#${((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1)}`;
  }

  private updateTexts(): void {
    const t = TRANSLATIONS[this.currentLang] || TRANSLATIONS.ko;

    const titleEl = document.getElementById('customThemeTitle');
    if (titleEl) titleEl.textContent = t.customThemeTitle;

    const descEl = document.getElementById('customThemeDesc');
    if (descEl) descEl.textContent = t.customThemeDesc;

    if (this.opacityLabelEl) {
      this.opacityLabelEl.textContent = t.customOpacityLabel || '창 투명도';
    }

    const presetsLabel = document.querySelector('[data-i18n-custom="presets"]');
    if (presetsLabel) presetsLabel.textContent = t.customThemePresets;

    const bgLabel = document.querySelector('[data-i18n-custom="bg"]');
    if (bgLabel) bgLabel.textContent = t.customThemeBg;

    const surfaceLabel = document.querySelector('[data-i18n-custom="surface"]');
    if (surfaceLabel) surfaceLabel.textContent = t.customThemeSurface;

    const accentLabel = document.querySelector('[data-i18n-custom="accent"]');
    if (accentLabel) accentLabel.textContent = t.customThemeAccent;

    const textLabel = document.querySelector('[data-i18n-custom="text"]');
    if (textLabel) textLabel.textContent = t.customThemeText;

    const resetBtn = document.getElementById('customModalReset');
    if (resetBtn) resetBtn.textContent = t.customThemeReset;

    const saveBtn = document.getElementById('customModalSave');
    if (saveBtn) saveBtn.textContent = t.customThemeSave;

    if (this.collapseBtn) {
      const label = this.isCollapsed ? t.customWindowExpand : t.customWindowCollapse;
      this.collapseBtn.title = label;
      this.collapseBtn.setAttribute('aria-label', label);
    }

    if (this.modeBadgeEl) {
      this.modeBadgeEl.textContent = this.isCollapsed
        ? t.customWindowCollapse || '접힘'
        : 'Live GUI';
    }

    const fontLabel = document.getElementById('customFontFamilyLabel');
    if (fontLabel) fontLabel.textContent = t.customFontFamily;
    const fontScaleLabel = document.getElementById('customFontScaleLabel');
    if (fontScaleLabel) fontScaleLabel.textContent = t.customFontScale;
    const radiusLabel = document.getElementById('customRadiusLabel');
    if (radiusLabel) radiusLabel.textContent = t.customRadius;
    const blurLabel = document.getElementById('customBlurLabel');
    if (blurLabel) blurLabel.textContent = t.customBlur;
    const densityLabel = document.getElementById('customDensityLabel');
    if (densityLabel) densityLabel.textContent = t.customDensity;

    const optSystem = document.querySelector<HTMLOptionElement>('#customFontSelect option[value="system"]');
    if (optSystem) optSystem.textContent = t.fontSystem;
    const optMono = document.querySelector<HTMLOptionElement>('#customFontSelect option[value="mono"]');
    if (optMono) optMono.textContent = t.fontMono;
    const optNeo = document.querySelector<HTMLOptionElement>('#customFontSelect option[value="neo"]');
    if (optNeo) optNeo.textContent = t.fontNeo;
    const optSerif = document.querySelector<HTMLOptionElement>('#customFontSelect option[value="serif"]');
    if (optSerif) optSerif.textContent = t.fontSerif;

    const compactBtn = document.getElementById('densityCompactBtn');
    if (compactBtn) compactBtn.textContent = t.densityCompact;
    const normalBtn = document.getElementById('densityNormalBtn');
    if (normalBtn) normalBtn.textContent = t.densityNormal;
    const relaxedBtn = document.getElementById('densityRelaxedBtn');
    if (relaxedBtn) relaxedBtn.textContent = t.densityRelaxed;
  }
}
