/**
 * KRC Labs — FloatingWindow Common Base Engine
 * Pure OOP, reusable floating desktop GUI window component.
 * Provides draggable titlebar, resizable corner handle, collapsible minibar,
 * active window z-index focus stacking, and local storage persistence.
 */

import { LanguageCode } from '../types';

export type ResizeDirection = 'n' | 's' | 'e' | 'w' | 'ne' | 'nw' | 'se' | 'sw';

export interface FloatingWindowPos {
  left: number;
  top: number;
  width?: number;
  height?: number;
  collapsed?: boolean;
}

export interface FloatingWindowConfig {
  containerId: string;
  windowId: string;
  titlebarId: string;
  collapseBtnId: string;
  closeBtnId: string;
  resizeHandleId: string;
  modeBadgeId?: string;
  storageKey: string;
  initialPos?: {
    leftOffsetFromRight?: number;
    top?: number;
    width?: number;
    height?: number;
  };
  minWidth?: number;
  minHeight?: number;
  badgeActiveText?: string;
  badgeCollapsedText?: string;
}

export class FloatingWindow {
  // Global z-index stack tracker across all floating windows
  private static globalZIndex: number = 1050;
  private static activeInstances: Set<FloatingWindow> = new Set();
  private static escListenerAttached: boolean = false;

  private static initGlobalShortcuts(): void {
    if (FloatingWindow.escListenerAttached) return;
    FloatingWindow.escListenerAttached = true;

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const openWindows = Array.from(FloatingWindow.activeInstances).filter((w) => w.isOpen());
        if (openWindows.length === 0) return;

        // Sort descending by zIndex to close top-most active window
        openWindows.sort((a, b) => {
          const za = parseInt(a.containerEl?.style.zIndex || a.windowEl?.style.zIndex || '0', 10);
          const zb = parseInt(b.containerEl?.style.zIndex || b.windowEl?.style.zIndex || '0', 10);
          return zb - za;
        });

        openWindows[0].close();
      }
    });
  }

  public readonly config: FloatingWindowConfig;
  protected currentLang: LanguageCode = 'en';

  public containerEl: HTMLElement | null = null;
  public windowEl: HTMLElement | null = null;
  public titlebarEl: HTMLElement | null = null;
  public collapseBtn: HTMLButtonElement | null = null;
  public closeBtn: HTMLElement | null = null;
  public resizeHandleEl: HTMLElement | null = null;
  public modeBadgeEl: HTMLElement | null = null;

  protected isCollapsed: boolean = false;
  protected isDragging: boolean = false;
  protected isResizing: boolean = false;
  protected activeResizeDir: ResizeDirection | null = null;

  private dragStart = { mouseX: 0, mouseY: 0, winLeft: 0, winTop: 0 };
  private resizeStart = {
    mouseX: 0,
    mouseY: 0,
    winLeft: 0,
    winTop: 0,
    winWidth: 420,
    winHeight: 460,
  };

  constructor(config: FloatingWindowConfig) {
    this.config = {
      minWidth: 320,
      minHeight: 200,
      badgeActiveText: 'GUI',
      badgeCollapsedText: 'Min',
      ...config,
    };
    FloatingWindow.activeInstances.add(this);
    FloatingWindow.initGlobalShortcuts();
  }

  public init(lang: LanguageCode = 'en'): void {
    this.currentLang = lang;
    this.containerEl = document.getElementById(this.config.containerId);
    this.windowEl = document.getElementById(this.config.windowId);
    this.titlebarEl = document.getElementById(this.config.titlebarId);
    this.collapseBtn = document.getElementById(this.config.collapseBtnId) as HTMLButtonElement | null;
    this.closeBtn = document.getElementById(this.config.closeBtnId);
    this.resizeHandleEl = document.getElementById(this.config.resizeHandleId);
    if (this.config.modeBadgeId) {
      this.modeBadgeEl = document.getElementById(this.config.modeBadgeId);
    }

    this.restorePosition();
    this.bindWindowEvents();
    this.initDrag();
    this.initResize();

    window.addEventListener('resize', () => {
      this.clampToViewport();
    });
  }

  public setLanguage(lang: LanguageCode): void {
    this.currentLang = lang;
  }

  public open(): void {
    if (!this.containerEl || !this.windowEl) return;
    this.containerEl.classList.add('open');
    this.containerEl.setAttribute('aria-hidden', 'false');

    if (!this.windowEl.style.left && !this.windowEl.style.top) {
      this.resetPosition();
    } else {
      this.clampToViewport();
    }
    this.bringToFront();
  }

  public close(): void {
    if (!this.containerEl) return;
    this.containerEl.classList.remove('open');
    this.containerEl.setAttribute('aria-hidden', 'true');
    this.windowEl?.classList.remove('is-active-window');
  }

  public isOpen(): boolean {
    return this.containerEl?.classList.contains('open') || false;
  }

  public toggle(): void {
    if (this.isOpen()) {
      this.close();
    } else {
      this.open();
    }
  }

  public toggleCollapse(): void {
    this.setCollapsed(!this.isCollapsed);
  }

  public setCollapsed(collapsed: boolean): void {
    this.isCollapsed = collapsed;
    if (!this.windowEl) return;

    if (this.isCollapsed) {
      this.windowEl.classList.add('is-collapsed');
      if (this.collapseBtn) {
        this.collapseBtn.title = 'Expand';
        this.collapseBtn.setAttribute('aria-label', 'Expand');
      }
      if (this.modeBadgeEl) {
        this.modeBadgeEl.textContent = this.config.badgeCollapsedText || 'Min';
      }
    } else {
      this.windowEl.classList.remove('is-collapsed');
      if (this.collapseBtn) {
        this.collapseBtn.title = 'Collapse';
        this.collapseBtn.setAttribute('aria-label', 'Collapse');
      }
      if (this.modeBadgeEl) {
        this.modeBadgeEl.textContent = this.config.badgeActiveText || 'GUI';
      }
    }
    this.savePosition();
  }

  public getIsCollapsed(): boolean {
    return this.isCollapsed;
  }

  public bringToFront(): void {
    if (!this.windowEl) return;
    FloatingWindow.globalZIndex += 1;
    if (FloatingWindow.globalZIndex > 18000) {
      FloatingWindow.globalZIndex = 1050;
    }
    this.windowEl.style.zIndex = String(FloatingWindow.globalZIndex);
    if (this.containerEl) {
      this.containerEl.style.zIndex = String(FloatingWindow.globalZIndex);
    }

    FloatingWindow.activeInstances.forEach((inst) => {
      inst.windowEl?.classList.remove('is-active-window');
    });
    this.windowEl.classList.add('is-active-window');
  }

  public resetPosition(): void {
    if (!this.windowEl) return;
    const vpW = window.innerWidth;
    if (vpW <= 600) {
      this.windowEl.style.left = '12px';
      this.windowEl.style.right = '12px';
      this.windowEl.style.width = 'calc(100vw - 24px)';
      this.windowEl.style.maxWidth = 'calc(100vw - 24px)';
      this.windowEl.style.top = '64px';
      return;
    }
    const defaultW = Math.min(this.config.initialPos?.width || 440, vpW - 32);
    const offsetRight = this.config.initialPos?.leftOffsetFromRight ?? 24;
    const left = Math.max(16, vpW - defaultW - offsetRight);
    const top = this.config.initialPos?.top ?? 76;

    this.windowEl.style.left = `${left}px`;
    this.windowEl.style.top = `${top}px`;
    this.windowEl.style.width = `${defaultW}px`;
    if (this.config.initialPos?.height) {
      this.windowEl.style.height = `${this.config.initialPos.height}px`;
    }
  }

  public clampToViewport(): void {
    if (!this.windowEl) return;
    const vpW = window.innerWidth;
    const vpH = window.innerHeight;

    if (vpW <= 600) {
      this.windowEl.style.left = '12px';
      this.windowEl.style.right = '12px';
      this.windowEl.style.width = 'calc(100vw - 24px)';
      this.windowEl.style.maxWidth = 'calc(100vw - 24px)';
      this.windowEl.style.top = '64px';
      return;
    }

    const rect = this.windowEl.getBoundingClientRect();
    const effectiveW = Math.min(rect.width, vpW - 16);
    const clampedLeft = Math.max(8, Math.min(vpW - effectiveW - 8, rect.left));
    const clampedTop = Math.max(8, Math.min(vpH - 44, rect.top));

    this.windowEl.style.left = `${clampedLeft}px`;
    this.windowEl.style.top = `${clampedTop}px`;
    if (rect.width > vpW - 16) {
      this.windowEl.style.width = `${vpW - 16}px`;
    }
  }

  private restorePosition(): void {
    if (!this.windowEl) return;
    const vpW = window.innerWidth;
    if (vpW <= 600) {
      this.windowEl.style.left = '12px';
      this.windowEl.style.right = '12px';
      this.windowEl.style.width = 'calc(100vw - 24px)';
      this.windowEl.style.maxWidth = 'calc(100vw - 24px)';
      this.windowEl.style.top = '64px';
      return;
    }
    try {
      const raw = localStorage.getItem(this.config.storageKey);
      if (raw) {
        const pos: FloatingWindowPos = JSON.parse(raw);
        const vpH = window.innerHeight;

        const effectiveW = Math.min(pos.width || 440, vpW - 16);
        const clampedLeft = Math.max(8, Math.min(vpW - effectiveW - 8, pos.left));
        const clampedTop = Math.max(8, Math.min(vpH - 44, pos.top));

        this.windowEl.style.left = `${clampedLeft}px`;
        this.windowEl.style.top = `${clampedTop}px`;
        if (pos.width) {
          this.windowEl.style.width = `${effectiveW}px`;
        }
        if (pos.height) {
          this.windowEl.style.height = `${Math.min(pos.height, vpH - 60)}px`;
        }
        if (pos.collapsed) {
          this.setCollapsed(true);
        }
      }
    } catch {
      // Use CSS defaults
    }
  }

  public savePosition(): void {
    if (!this.windowEl) return;
    try {
      const rect = this.windowEl.getBoundingClientRect();
      const pos: FloatingWindowPos = {
        left: Math.round(rect.left),
        top: Math.round(rect.top),
        width: Math.round(rect.width),
        height: Math.round(rect.height),
        collapsed: this.isCollapsed,
      };
      localStorage.setItem(this.config.storageKey, JSON.stringify(pos));
    } catch {
      // Storage unavailable
    }
  }

  private bindWindowEvents(): void {
    // Focus on click/pointerdown anywhere on the window or container
    const bringActive = () => {
      this.bringToFront();
    };

    this.windowEl?.addEventListener('mousedown', bringActive);
    this.windowEl?.addEventListener('pointerdown', bringActive);
    this.containerEl?.addEventListener('mousedown', bringActive);
    this.containerEl?.addEventListener('pointerdown', bringActive);

    // Close button
    this.closeBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.close();
    });

    // Collapse toggle button
    this.collapseBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.toggleCollapse();
    });

    // Titlebar double click to toggle collapse
    this.titlebarEl?.addEventListener('dblclick', (e) => {
      if ((e.target as HTMLElement).closest('button')) return;
      this.toggleCollapse();
    });
  }

  private isInteractiveTarget(target: HTMLElement | null, clientX: number, clientY: number): boolean {
    if (!target) return true;

    // 1. Standard HTML form controls, buttons, links
    if (target.closest('button, input, select, textarea, a, option, datalist')) {
      return true;
    }

    // 2. Interactive ARIA roles
    if (
      target.closest(
        '[role="button"], [role="link"], [role="slider"], [role="switch"], [role="tab"], [role="checkbox"], [role="radio"]'
      )
    ) {
      return true;
    }

    // 3. Form labels associated with inputs
    const label = target.closest('label');
    if (label && (label.htmlFor || label.querySelector('input, select, textarea'))) {
      return true;
    }

    // 4. Color input wrapper
    if (target.closest('.color-input-wrapper')) {
      return true;
    }

    // 5. Window resize handles (8-way edges and corners)
    if (
      target.closest(
        '.custom-window-resize-handle, .win-resize-edge, .win-resize-corner, [data-resize-dir]'
      )
    ) {
      return true;
    }

    // 6. Explicit no-drag markers
    if (target.closest('[data-no-drag], .no-drag, [contenteditable="true"]')) {
      return true;
    }

    // 7. Scrollbar guard on scrollable containers
    const scrollContainer = target.closest('.custom-window-body, .help-window-body') as HTMLElement | null;
    if (scrollContainer && scrollContainer.scrollHeight > scrollContainer.clientHeight) {
      const rect = scrollContainer.getBoundingClientRect();
      const scrollbarWidth = scrollContainer.offsetWidth - scrollContainer.clientWidth;
      if (scrollbarWidth > 0 && clientX >= rect.right - scrollbarWidth - 4) {
        return true;
      }
    }

    return false;
  }

  private initDrag(): void {
    if (!this.titlebarEl || !this.windowEl) return;

    const onStart = (clientX: number, clientY: number) => {
      if (!this.windowEl) return;
      this.isDragging = true;
      this.windowEl.classList.add('is-dragging');
      this.bringToFront();

      const rect = this.windowEl.getBoundingClientRect();
      this.dragStart = {
        mouseX: clientX,
        mouseY: clientY,
        winLeft: rect.left,
        winTop: rect.top,
      };
    };

    const onMove = (clientX: number, clientY: number) => {
      if (!this.isDragging || !this.windowEl) return;
      const deltaX = clientX - this.dragStart.mouseX;
      const deltaY = clientY - this.dragStart.mouseY;

      const rect = this.windowEl.getBoundingClientRect();
      const vpW = window.innerWidth;
      const vpH = window.innerHeight;

      const effectiveW = Math.min(rect.width, vpW - 24);
      const newLeft = vpW <= 600 ? 12 : Math.max(8, Math.min(vpW - effectiveW - 8, this.dragStart.winLeft + deltaX));
      const newTop = Math.max(8, Math.min(vpH - 44, this.dragStart.winTop + deltaY));

      this.windowEl.style.left = `${newLeft}px`;
      this.windowEl.style.top = `${newTop}px`;
      if (vpW <= 600) {
        this.windowEl.style.right = '12px';
        this.windowEl.style.width = 'calc(100vw - 24px)';
      } else {
        this.windowEl.style.right = 'auto';
        this.windowEl.style.bottom = 'auto';
      }
    };

    const onEnd = () => {
      if (!this.isDragging) return;
      this.isDragging = false;
      this.windowEl?.classList.remove('is-dragging');
      this.savePosition();
    };

    // Unified mouse drag: Allows moving from titlebar AND other non-interactive surfaces of the window
    this.windowEl.addEventListener('mousedown', (e) => {
      if (e.button !== 0) return;
      const target = e.target as HTMLElement | null;
      if (!target) return;

      if (this.isInteractiveTarget(target, e.clientX, e.clientY)) {
        return;
      }

      e.preventDefault();
      onStart(e.clientX, e.clientY);

      const moveHandler = (moveEv: MouseEvent) => onMove(moveEv.clientX, moveEv.clientY);
      const upHandler = () => {
        window.removeEventListener('mousemove', moveHandler);
        window.removeEventListener('mouseup', upHandler);
        onEnd();
      };
      window.addEventListener('mousemove', moveHandler);
      window.addEventListener('mouseup', upHandler);
    });

    // Touch drag: Titlebar & designated surfaces drag, while scrollable body permits normal touch scroll
    this.windowEl.addEventListener(
      'touchstart',
      (e) => {
        const target = e.target as HTMLElement | null;
        if (!target) return;
        if (this.isInteractiveTarget(target, e.touches[0].clientX, e.touches[0].clientY)) return;

        // In scrollable body, only drag touch on designated drag handles to preserve native touch scrolling
        const isExplicitDragZone = Boolean(
          target.closest(
            `#${this.config.titlebarId}, .custom-preview-box, .design-engine-header, [data-window-drag]`
          )
        );
        const isInsideScrollableBody = Boolean(target.closest('.custom-window-body, .help-window-body'));

        if (isInsideScrollableBody && !isExplicitDragZone) {
          return;
        }

        const touch = e.touches[0];
        onStart(touch.clientX, touch.clientY);

        const touchMoveHandler = (moveEv: TouchEvent) => {
          if (this.isDragging) {
            moveEv.preventDefault();
            const t = moveEv.touches[0];
            onMove(t.clientX, t.clientY);
          }
        };

        const touchEndHandler = () => {
          window.removeEventListener('touchmove', touchMoveHandler);
          window.removeEventListener('touchend', touchEndHandler);
          onEnd();
        };

        window.addEventListener('touchmove', touchMoveHandler, { passive: false });
        window.addEventListener('touchend', touchEndHandler);
      },
      { passive: true }
    );
  }

  private initResize(): void {
    if (!this.windowEl) return;

    const minW = this.config.minWidth || 320;
    const minH = this.config.minHeight || 200;

    // Dynamically inject 8-direction handles (Edges: Top, Bottom, Left, Right / Corners: TL, TR, BL, BR)
    this.createResizeHandles();

    const onStart = (dir: ResizeDirection, clientX: number, clientY: number) => {
      if (!this.windowEl || this.isCollapsed) return;
      this.isResizing = true;
      this.activeResizeDir = dir;
      this.bringToFront();
      const rect = this.windowEl.getBoundingClientRect();
      this.resizeStart = {
        mouseX: clientX,
        mouseY: clientY,
        winLeft: rect.left,
        winTop: rect.top,
        winWidth: rect.width,
        winHeight: rect.height,
      };
      this.windowEl.classList.add('is-resizing');
    };

    const onMove = (clientX: number, clientY: number) => {
      if (!this.isResizing || !this.windowEl || !this.activeResizeDir) return;
      const deltaX = clientX - this.resizeStart.mouseX;
      const deltaY = clientY - this.resizeStart.mouseY;

      const vpW = window.innerWidth;
      const vpH = window.innerHeight;
      const dir = this.activeResizeDir;

      let newWidth = this.resizeStart.winWidth;
      let newHeight = this.resizeStart.winHeight;
      let newLeft = this.resizeStart.winLeft;
      let newTop = this.resizeStart.winTop;

      // 1. Horizontal Resize
      if (dir === 'e' || dir === 'ne' || dir === 'se') {
        const rawW = this.resizeStart.winWidth + deltaX;
        newWidth = Math.max(minW, Math.min(vpW - this.resizeStart.winLeft - 8, rawW));
      } else if (dir === 'w' || dir === 'nw' || dir === 'sw') {
        const rawW = this.resizeStart.winWidth - deltaX;
        const clampedW = Math.max(minW, Math.min(this.resizeStart.winLeft + this.resizeStart.winWidth - 8, rawW));
        newLeft = this.resizeStart.winLeft + (this.resizeStart.winWidth - clampedW);
        newWidth = clampedW;
      }

      // 2. Vertical Resize
      if (dir === 's' || dir === 'se' || dir === 'sw') {
        const rawH = this.resizeStart.winHeight + deltaY;
        newHeight = Math.max(minH, Math.min(vpH - this.resizeStart.winTop - 8, rawH));
      } else if (dir === 'n' || dir === 'ne' || dir === 'nw') {
        const rawH = this.resizeStart.winHeight - deltaY;
        const clampedH = Math.max(minH, Math.min(this.resizeStart.winTop + this.resizeStart.winHeight - 44, rawH));
        newTop = this.resizeStart.winTop + (this.resizeStart.winHeight - clampedH);
        newHeight = clampedH;
      }

      this.windowEl.style.width = `${newWidth}px`;
      this.windowEl.style.height = `${newHeight}px`;
      if (dir === 'w' || dir === 'nw' || dir === 'sw') {
        this.windowEl.style.left = `${newLeft}px`;
      }
      if (dir === 'n' || dir === 'ne' || dir === 'nw') {
        this.windowEl.style.top = `${newTop}px`;
      }
    };

    const onEnd = () => {
      if (!this.isResizing) return;
      this.isResizing = false;
      this.activeResizeDir = null;
      this.windowEl?.classList.remove('is-resizing');
      this.savePosition();
    };

    this.bindDirectionHandles(onStart, onMove, onEnd);
  }

  private createResizeHandles(): void {
    if (!this.windowEl) return;

    if (this.windowEl.querySelector('.win-resize-edge')) return;

    const directions: Array<{ type: 'edge' | 'corner'; dir: ResizeDirection; cls: string; title: string }> = [
      { type: 'edge', dir: 'n', cls: 'edge-t', title: 'Resize top' },
      { type: 'edge', dir: 's', cls: 'edge-b', title: 'Resize bottom' },
      { type: 'edge', dir: 'w', cls: 'edge-l', title: 'Resize left' },
      { type: 'edge', dir: 'e', cls: 'edge-r', title: 'Resize right' },
      { type: 'corner', dir: 'nw', cls: 'corner-tl', title: 'Resize top-left' },
      { type: 'corner', dir: 'ne', cls: 'corner-tr', title: 'Resize top-right' },
      { type: 'corner', dir: 'sw', cls: 'corner-bl', title: 'Resize bottom-left' },
      { type: 'corner', dir: 'se', cls: 'corner-br', title: 'Resize bottom-right' },
    ];

    directions.forEach(({ type, dir, cls, title }) => {
      // If legacy bottom-right handle exists, annotate it
      if (dir === 'se' && this.resizeHandleEl) {
        this.resizeHandleEl.classList.add('win-resize-corner', 'corner-br');
        this.resizeHandleEl.setAttribute('data-resize-dir', 'se');
        return;
      }

      const el = document.createElement('div');
      el.className = type === 'edge' ? `win-resize-edge ${cls}` : `win-resize-corner ${cls}`;
      el.setAttribute('data-resize-dir', dir);
      el.setAttribute('title', title);
      el.setAttribute('aria-hidden', 'true');
      this.windowEl?.appendChild(el);
    });
  }

  private bindDirectionHandles(
    onStart: (dir: ResizeDirection, x: number, y: number) => void,
    onMove: (x: number, y: number) => void,
    onEnd: () => void
  ): void {
    if (!this.windowEl) return;

    const handles = this.windowEl.querySelectorAll<HTMLElement>('[data-resize-dir]');
    handles.forEach((h) => {
      const dir = h.getAttribute('data-resize-dir') as ResizeDirection;
      if (!dir) return;

      h.addEventListener('mousedown', (e) => {
        if (e.button !== 0) return;
        e.preventDefault();
        e.stopPropagation();
        onStart(dir, e.clientX, e.clientY);

        const moveHandler = (moveEv: MouseEvent) => {
          onMove(moveEv.clientX, moveEv.clientY);
        };

        const upHandler = () => {
          window.removeEventListener('mousemove', moveHandler);
          window.removeEventListener('mouseup', upHandler);
          onEnd();
        };

        window.addEventListener('mousemove', moveHandler);
        window.addEventListener('mouseup', upHandler);
      });

      h.addEventListener(
        'touchstart',
        (e) => {
          const touch = e.touches[0];
          if (!touch) return;
          e.stopPropagation();
          onStart(dir, touch.clientX, touch.clientY);

          const touchMoveHandler = (moveEv: TouchEvent) => {
            if (this.isResizing) {
              moveEv.preventDefault();
              const t = moveEv.touches[0];
              onMove(t.clientX, t.clientY);
            }
          };

          const touchEndHandler = () => {
            window.removeEventListener('touchmove', touchMoveHandler);
            window.removeEventListener('touchend', touchEndHandler);
            onEnd();
          };

          window.addEventListener('touchmove', touchMoveHandler, { passive: false });
          window.addEventListener('touchend', touchEndHandler);
        },
        { passive: false }
      );
    });
  }
}
