/**
 * KRC Labs — HelpModal Component (Floating Guide Window GUI)
 * Movable, Resizable, and Collapsible Desktop-class System Guide Window.
 * Inherits and leverages the common FloatingWindow engine for DRY design.
 * Explains Theme Families, Custom Window GUI manipulation, Floating Scroll Button Pinning, and Shortcuts.
 * Features:
 *  - Real-time Hot-Reload Opacity Slider (Default 85%, Range 40% - 100%)
 *  - F5 LocalStorage Persistence
 *  - 10-Language Parity
 */

import { LanguageCode } from '../types';
import { TRANSLATIONS } from '../locales';
import { FloatingWindow } from './FloatingWindow';

export class HelpModal extends FloatingWindow {
  private static readonly STORAGE_OPACITY_KEY = 'krc_help_win_opacity';
  public static readonly DEFAULT_OPACITY = 85;
  public static readonly MIN_OPACITY = 40;
  public static readonly MAX_OPACITY = 100;

  private bottomCloseBtn: HTMLElement | null = null;
  private opacityRange: HTMLInputElement | null = null;
  private opacityValBadge: HTMLElement | null = null;
  private opacityLabelEl: HTMLElement | null = null;
  private currentOpacity: number = HelpModal.DEFAULT_OPACITY;

  constructor() {
    super({
      containerId: 'helpModal',
      windowId: 'helpWindowRoot',
      titlebarId: 'helpWindowTitlebar',
      collapseBtnId: 'helpWindowCollapseBtn',
      closeBtnId: 'helpModalClose',
      resizeHandleId: 'helpWindowResizeHandle',
      modeBadgeId: 'helpWindowModeBadge',
      storageKey: 'krc_help_win_pos',
      initialPos: {
        leftOffsetFromRight: 28,
        top: 84,
        width: 520,
        height: 540,
      },
      minWidth: 320,
      minHeight: 220,
      badgeActiveText: 'Guide GUI',
      badgeCollapsedText: '접힘',
    });
  }

  public override init(lang: LanguageCode = 'ko'): void {
    super.init(lang);
    this.bottomCloseBtn = document.getElementById('helpModalCloseBtn');

    this.initOpacityControl();
    this.bindGuideEvents();
    this.updateTexts();
  }

  public override setLanguage(lang: LanguageCode): void {
    super.setLanguage(lang);
    this.updateTexts();
  }

  public override open(): void {
    // Pre-apply target opacity before window opens so there is zero flash of solid background
    this.applyOpacity(this.currentOpacity);
    super.open();
  }

  private initOpacityControl(): void {
    const controlEl = document.getElementById('helpOpacityControl');
    if (controlEl) {
      // Prevent mousedown, touchstart, click, dblclick from triggering titlebar window dragging or toggleCollapse
      const stopEvents = ['mousedown', 'touchstart', 'click', 'dblclick'];
      stopEvents.forEach((evtName) => {
        controlEl.addEventListener(evtName, (e) => {
          e.stopPropagation();
        });
      });
    }

    this.opacityRange = document.getElementById('helpWindowOpacityRange') as HTMLInputElement | null;
    this.opacityValBadge = document.getElementById('helpWindowOpacityVal');
    this.opacityLabelEl = document.getElementById('helpOpacityLabel');

    // Restore saved opacity or fallback to default 85%
    const saved = localStorage.getItem(HelpModal.STORAGE_OPACITY_KEY);
    if (saved) {
      const parsed = parseInt(saved, 10);
      if (!isNaN(parsed) && parsed >= HelpModal.MIN_OPACITY && parsed <= HelpModal.MAX_OPACITY) {
        this.currentOpacity = parsed;
      }
    }

    this.applyOpacity(this.currentOpacity);

    if (this.opacityRange) {
      this.opacityRange.value = String(this.currentOpacity);
      // Hot-reload: apply opacity in real time on slider drag
      this.opacityRange.addEventListener('input', (e) => {
        e.stopPropagation();
        const val = parseInt(this.opacityRange?.value || String(HelpModal.DEFAULT_OPACITY), 10);
        this.applyOpacity(val);
        localStorage.setItem(HelpModal.STORAGE_OPACITY_KEY, String(val));
      });
    }
  }

  public applyOpacity(val: number): void {
    const clamped = Math.max(HelpModal.MIN_OPACITY, Math.min(HelpModal.MAX_OPACITY, val));
    this.currentOpacity = clamped;

    if (this.windowEl) {
      this.windowEl.style.setProperty('--window-opacity', `${clamped / 100}`);
      this.windowEl.style.opacity = `${clamped / 100}`;
    }

    if (this.opacityValBadge) {
      this.opacityValBadge.textContent = `${clamped}%`;
    }

    if (this.opacityRange && this.opacityRange.value !== String(clamped)) {
      this.opacityRange.value = String(clamped);
    }
  }

  public getOpacity(): number {
    return this.currentOpacity;
  }

  private bindGuideEvents(): void {
    // Additional bottom close button inside window body
    this.bottomCloseBtn?.addEventListener('click', (e) => {
      e.stopPropagation();
      this.close();
    });

    // Keyboard shortcut: '?' opens/toggles help (Esc is handled globally by FloatingWindow)
    document.addEventListener('keydown', (e) => {
      const activeTag = (document.activeElement?.tagName || '').toUpperCase();
      const isInput = activeTag === 'INPUT' || activeTag === 'TEXTAREA';

      if (e.key === '?' && !isInput) {
        e.preventDefault();
        this.toggle();
      }
    });
  }

  private updateTexts(): void {
    const t = TRANSLATIONS[this.currentLang] || TRANSLATIONS.ko;

    const titleEl = document.getElementById('helpModalTitle');
    if (titleEl) titleEl.textContent = t.helpTitle;

    const descEl = document.getElementById('helpModalDesc');
    if (descEl) descEl.textContent = t.helpDesc;

    if (this.opacityLabelEl) {
      this.opacityLabelEl.textContent = t.helpOpacityLabel || '창 투명도';
    }

    const themeTitle = document.querySelector('[data-i18n="helpGuideThemeTitle"]');
    if (themeTitle) themeTitle.textContent = t.helpGuideThemeTitle;

    const winTitle = document.querySelector('[data-i18n="helpGuideWindowTitle"]');
    if (winTitle) winTitle.textContent = t.helpGuideWindowTitle;

    const scrollTitle = document.querySelector('[data-i18n="helpGuideScrollTitle"]');
    if (scrollTitle) scrollTitle.textContent = t.helpGuideScrollTitle;

    const shortcutsTitle = document.querySelector('[data-i18n="helpGuideShortcutsTitle"]');
    if (shortcutsTitle) shortcutsTitle.textContent = t.helpGuideShortcutsTitle;

    const themeItem = document.querySelector('[data-help-item="theme"]');
    if (themeItem) themeItem.textContent = t.helpThemeGuide;

    const windowItem = document.querySelector('[data-help-item="window"]');
    if (windowItem) windowItem.textContent = t.helpWindowGuide;

    const scrollItem = document.querySelector('[data-help-item="scroll"]');
    if (scrollItem) scrollItem.textContent = t.helpScrollGuide;

    const shortcutsItem = document.querySelector('[data-help-item="shortcuts"]');
    if (shortcutsItem) shortcutsItem.textContent = t.helpShortcutsGuide;

    const closeBtnText = document.getElementById('helpModalCloseBtnText');
    if (closeBtnText) closeBtnText.textContent = t.helpClose;

    if (this.collapseBtn) {
      const label = this.isCollapsed ? t.customWindowExpand || 'Expand' : t.customWindowCollapse || 'Collapse';
      this.collapseBtn.title = label;
      this.collapseBtn.setAttribute('aria-label', label);
    }

    if (this.modeBadgeEl) {
      this.modeBadgeEl.textContent = this.isCollapsed
        ? t.customWindowCollapse || '접힘'
        : 'Guide GUI';
    }
  }
}
