/**
 * KRC Labs — Header Component
 * Renders navigation bar, brand avatar, title, status tag, and mounts ThemeDropdown and LanguageDropdown.
 */

import { LanguageCode } from '../types';
import { TRANSLATIONS } from '../locales';
import { ThemeDropdown } from './ThemeDropdown';
import { LanguageDropdown } from './LanguageDropdown';

export class Header {
  private currentLang: LanguageCode = 'ko';
  private themeDropdown: ThemeDropdown;
  private langDropdown: LanguageDropdown;
  private headerEl: HTMLElement | null = null;

  constructor(themeDropdown?: ThemeDropdown, langDropdown?: LanguageDropdown) {
    this.themeDropdown = themeDropdown || new ThemeDropdown();
    this.langDropdown = langDropdown || new LanguageDropdown();
  }

  public init(lang: LanguageCode = 'ko'): void {
    this.currentLang = lang;
    this.headerEl = document.querySelector('header');

    // Mount / initialize child dropdowns
    this.themeDropdown.init(lang);
    this.langDropdown.init(lang);

    this.updateTexts();
  }

  public setLanguage(lang: LanguageCode): void {
    this.currentLang = lang;
    this.themeDropdown.setLanguage(lang);
    this.langDropdown.setLanguage(lang);
    this.updateTexts();
  }

  public getThemeDropdown(): ThemeDropdown {
    return this.themeDropdown;
  }

  public getLanguageDropdown(): LanguageDropdown {
    return this.langDropdown;
  }

  private updateTexts(): void {
    const t = TRANSLATIONS[this.currentLang] || TRANSLATIONS.ko;

    const badgeStatus = document.querySelector<HTMLElement>('[data-i18n="badgeStatus"]');
    if (badgeStatus) badgeStatus.textContent = t.badgeStatus;

    document.querySelectorAll<HTMLElement>('[data-i18n="navBlog"]').forEach((el) => {
      el.textContent = t.navBlog;
    });

    document.querySelectorAll<HTMLElement>('[data-i18n="navDocs"]').forEach((el) => {
      el.textContent = t.navDocs;
    });

    document.querySelectorAll<HTMLElement>('[data-i18n="navFaq"]').forEach((el) => {
      el.textContent = t.navFaq;
    });

    document.querySelectorAll<HTMLAnchorElement>('[data-i18n="navRss"]').forEach((el) => {
      el.setAttribute('title', t.navRss);
      el.setAttribute('aria-label', t.navRss);
      el.setAttribute('href', `feed.${this.currentLang}.xml`);
    });

    document.querySelectorAll<HTMLElement>('[data-i18n="helpTriggerText"]').forEach((el) => {
      el.textContent = t.helpTriggerText;
    });

    const navSystems = document.querySelector<HTMLAnchorElement>('[data-i18n="navSystems"]');
    if (navSystems) navSystems.textContent = t.navSystems;
  }
}
