/**
 * KRC Labs — LanguageDropdown Component
 * Expert-tier 10-language selector popover with full WAI-ARIA listbox & keyboard navigation.
 */

import { LanguageCode } from '../types';
import { LANGUAGE_META } from '../locales';

export class LanguageDropdown {
  private currentLang: LanguageCode = 'en';
  private triggerBtn: HTMLButtonElement | null = null;
  private menuEl: HTMLElement | null = null;
  private labelEl: HTMLElement | null = null;
  private listeners: Array<(lang: LanguageCode) => void> = [];
  private focusedIndex = 0;

  public init(currentLang: LanguageCode = 'en'): void {
    this.currentLang = currentLang;

    this.triggerBtn = document.getElementById('langTrigger') as HTMLButtonElement | null;
    this.menuEl = document.getElementById('langMenu');
    this.labelEl = document.getElementById('langTriggerLabel');

    this.setupAria();
    this.updateControls();
    this.bindEvents();
  }

  public setLanguage(lang: LanguageCode): void {
    this.currentLang = lang;
    this.updateControls();
  }

  public getLanguage(): LanguageCode {
    return this.currentLang;
  }

  public onLanguageChange(listener: (lang: LanguageCode) => void): void {
    this.listeners.push(listener);
  }

  public open(): void {
    this.closeAllMenus();
    if (!this.menuEl || !this.triggerBtn) return;

    this.menuEl.classList.add('open');
    this.triggerBtn.setAttribute('aria-expanded', 'true');

    // Focus active or first item
    const items = this.getItems();
    const activeIdx = items.findIndex((it) => it.getAttribute('data-lang-val') === this.currentLang);
    this.focusedIndex = activeIdx >= 0 ? activeIdx : 0;
    this.focusItem(this.focusedIndex);
  }

  public close(): void {
    if (!this.menuEl || !this.triggerBtn) return;
    this.menuEl.classList.remove('open');
    this.triggerBtn.setAttribute('aria-expanded', 'false');
  }

  public isOpen(): boolean {
    return this.menuEl?.classList.contains('open') || false;
  }

  private setupAria(): void {
    if (this.triggerBtn) {
      this.triggerBtn.setAttribute('aria-haspopup', 'listbox');
      this.triggerBtn.setAttribute('aria-expanded', 'false');
      this.triggerBtn.setAttribute('aria-controls', 'langMenu');
    }

    if (this.menuEl) {
      this.menuEl.setAttribute('role', 'listbox');
      this.menuEl.setAttribute('aria-label', 'Select Language');
      this.menuEl.setAttribute('tabindex', '-1');
    }

    const items = this.getItems();
    items.forEach((item) => {
      const lang = item.getAttribute('data-lang-val') || '';
      item.setAttribute('role', 'option');
      item.setAttribute('id', `lang-opt-${lang}`);
      item.setAttribute('tabindex', '-1');
    });
  }

  private getItems(): HTMLButtonElement[] {
    return Array.from(document.querySelectorAll<HTMLButtonElement>('.lang-item'));
  }

  private focusItem(index: number): void {
    const items = this.getItems();
    if (items.length === 0) return;

    // Wrap around boundaries
    if (index < 0) index = items.length - 1;
    if (index >= items.length) index = 0;

    this.focusedIndex = index;
    const target = items[index];
    target.focus();

    if (this.menuEl) {
      this.menuEl.setAttribute('aria-activedescendant', target.id);
    }
  }

  private updateControls(): void {
    if (this.labelEl) {
      const meta = LANGUAGE_META[this.currentLang];
      if (meta) {
        this.labelEl.textContent = meta.nativeName;
      }
    }

    const items = this.getItems();
    items.forEach((item) => {
      const code = item.getAttribute('data-lang-val') as LanguageCode;
      if (code === this.currentLang) {
        item.classList.add('active');
        item.setAttribute('aria-selected', 'true');
      } else {
        item.classList.remove('active');
        item.setAttribute('aria-selected', 'false');
      }
    });

    if (this.menuEl) {
      this.menuEl.setAttribute('aria-activedescendant', `lang-opt-${this.currentLang}`);
    }
  }

  private bindEvents(): void {
    if (this.triggerBtn) {
      this.triggerBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (this.isOpen()) {
          this.close();
        } else {
          this.open();
        }
      });

      // Keyboard opening from trigger
      this.triggerBtn.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          this.open();
        }
      });
    }

    const items = this.getItems();
    items.forEach((btn, idx) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const lang = btn.getAttribute('data-lang-val') as LanguageCode;
        if (lang) {
          this.selectLanguage(lang);
        }
      });

      // Keyboard navigation inside listbox
      btn.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowDown') {
          e.preventDefault();
          this.focusItem(this.focusedIndex + 1);
        } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          this.focusItem(this.focusedIndex - 1);
        } else if (e.key === 'Home') {
          e.preventDefault();
          this.focusItem(0);
        } else if (e.key === 'End') {
          e.preventDefault();
          this.focusItem(items.length - 1);
        } else if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          const lang = btn.getAttribute('data-lang-val') as LanguageCode;
          if (lang) {
            this.selectLanguage(lang);
          }
        } else if (e.key === 'Escape') {
          e.preventDefault();
          this.close();
          this.triggerBtn?.focus();
        } else if (e.key === 'Tab') {
          this.close();
        }
      });
    });

    // Close on click outside
    document.addEventListener('click', (e) => {
      const target = e.target as Node;
      if (this.isOpen() && !this.menuEl?.contains(target) && !this.triggerBtn?.contains(target)) {
        this.close();
      }
    });
  }

  private selectLanguage(lang: LanguageCode): void {
    this.currentLang = lang;
    this.updateControls();
    this.close();
    this.triggerBtn?.focus();
    this.listeners.forEach((fn) => fn(lang));
  }

  private closeAllMenus(): void {
    document.querySelectorAll('.dropdown-menu').forEach((el) => el.classList.remove('open'));
    document.querySelectorAll('.dropdown-trigger').forEach((el) => el.setAttribute('aria-expanded', 'false'));
  }
}
